const fs=require('fs');
const path=require('path');
const root=path.join(__dirname,'../..');
const guard=fs.readFileSync(path.join(root,'supabase/migrations/20260907064950_english_sprint_defer_trigger_guard.sql'),'utf8');
const migration=fs.readFileSync(path.join(root,'supabase/migrations/20260907065000_english_chatgpt_sprint_sets.sql'),'utf8');
const acl=fs.readFileSync(path.join(root,'supabase/migrations/20260907070000_english_chatgpt_sprint_state_acl.sql'),'utf8');
const repair=fs.readFileSync(path.join(root,'supabase/migrations/20260907071000_english_sprint_questionwise_luna_repair.sql'),'utf8');
const worker=fs.readFileSync(path.join(root,'supabase/functions/english-sprint-critic-worker/index.ts'),'utf8');
const landing=fs.readFileSync(path.join(root,'web-v2/components/chatgpt-sprint-sets.tsx'),'utf8');
const history=fs.readFileSync(path.join(root,'web-v2/components/sprint-report-history.tsx'),'utf8');
const page=fs.readFileSync(path.join(root,'web-v2/app/english/exam/page.tsx'),'utf8');
let bad=0;
const need=(s,x,m)=>s.includes(x)?console.log('✓ '+m):(bad++,console.error('✗ '+m));
const forbid=(s,x,m)=>!s.includes(x)?console.log('✓ '+m):(bad++,console.error('✗ '+m));
need(guard,"new.status='in_progress'",'Legacy defer trigger only promotes old in-progress inserts');
need(guard,"startImmediately','true'))='false'",'Legacy deferred-start behavior remains supported');
need(migration,'english.stage_chatgpt_sprint','ChatGPT staging owner exists');
need(migration,'sprint_self_critic_passes','ChatGPT self-critic is a hard gate');
need(migration,"status='critic_pending'",'Staged sets cannot start before Luna');
need(migration,"status='ready',set_no=v_set",'Set number is assigned only after final PASS');
need(migration,'Historical Sprint question repetition rejected','Historical exact replay is rejected');
need(migration,"Sprint creation now happens in ChatGPT",'Old app-side generation RPC is retired');
need(migration,"'*/10 * * * *'",'Luna transport retry safety-net is scheduled');
need(acl,'revoke all on function public.english_get_chatgpt_sprint_state() from public','Sprint state RPC revokes implicit PUBLIC execution');
need(acl,'revoke execute on function public.english_get_chatgpt_sprint_state() from anon','Sprint state RPC is unavailable anonymously');
need(acl,'grant execute on function public.english_get_chatgpt_sprint_state() to authenticated','Signed-in learner keeps Sprint state access');
need(acl,'grant execute on function public.english_get_chatgpt_sprint_state() to service_role','Service worker keeps Sprint state access');
need(repair,"critic_status='repair_needed'",'Isolated Luna defects enter targeted repair state');
need(repair,'english.repair_chatgpt_sprint','Connector-only targeted repair boundary exists');
need(repair,'Position % was not requested by Luna and is frozen','Passed positions are immutable during targeted repair');
need(repair,'must preserve target difficulty/domain','Repairs preserve the intended Sprint blueprint slot');
need(repair,'Historical Sprint question repetition rejected at repaired position','Repaired items cannot replay historical Sprint questions');
need(repair,'Duplicate Sprint question/concept after repair','Repairs cannot introduce exact/concept duplicates');
need(repair,"critic_status='queued'",'Successful targeted repair queues a fresh Luna full-set pass');
need(repair,"critic_status in ('queued','error')",'Retry scheduler only retries transport-ready states');
need(repair,"critic_status='processing'",'Only stale processing claims may be retried');
need(repair,"'repairPositions'",'Repair positions are exposed in Sprint state');
need(worker,'Audit the complete 25-question set together in ONE pass','Luna sees the full set together');
need(worker,'judge EACH QUESTION independently','Luna must decide question-wise');
need(worker,'enum:["PASS","REPAIR"]','Every Sprint item receives PASS or REPAIR');
need(worker,'enum:["PASS","REPAIR","REJECT_GLOBAL"]','Whole-set reject is a distinct global-only decision');
need(worker,'repairPositions','Luna returns exact positions to replace');
forbid(worker,'uniqueItems:true','Sprint Luna structured-output schema avoids unsupported uniqueItems');
need(worker,'all PASS positions are frozen','Luna understands good positions are retained');
need(worker,'noWithinSetSemanticDuplicate','Luna checks semantic overlap');
need(worker,'noHistoricalRepeat','Luna checks historical freshness');
need(worker,'difficultyCalibration','Luna checks real difficulty calibration');
need(worker,'reasoning:{effort:"medium"}','Final Luna gate uses bounded medium reasoning');
need(landing,'Type <b>create sprint</b> in ChatGPT','App tells learner to create set in ChatGPT');
need(landing,'Only Luna-flagged questions need refinement','App communicates targeted repair instead of whole-set waste');
need(landing,'Passed questions stay frozen','App explains that accepted questions are retained');
need(landing,'import ExamPreparationFinal','Luna-passed set reuses the mature timed Sprint runner');
need(landing,'<ExamPreparationFinal/>','Approved set delegates to existing runner lifecycle');
forbid(landing,'functions.invoke<SprintCreateResponse>("english-ssc-sprint"','New landing cannot call old generator');
need(page,'ChatgptSprintSets','Exam page uses ChatGPT set landing');
need(history,'Previous Sprint Sets','Completed tests are presented as set archive');
need(history,'p_days:3650','Archive is not limited to five days');
need(history,'label="Correct"','Review exposes Correct filter');
need(history,'label="Incorrect"','Review exposes Incorrect filter');
need(history,'label="Skipped"','Review exposes Skipped filter');
need(history,'← Previous','Question review has Previous navigation');
need(history,'Next →','Question review has Next navigation');
if(bad){console.error(`\nChatGPT Sprint set contracts failed with ${bad} defect(s).`);process.exit(1)}
console.log('\n✅ ChatGPT Sprint set contracts passed.');
